-- Server-only wake-up token for the scheduled publisher job.
-- The token is generated by Postgres and stored in a table that only the server can read:
-- only service_role is granted, and RLS is enabled with no policies, so no browser client,
-- anon key or logged-in user can read it.
create table if not exists public.job_tokens (
  name text primary key,
  secret text not null,
  created_at timestamptz not null default now()
);
grant all on public.job_tokens to service_role;
alter table public.job_tokens enable row level security;
insert into public.job_tokens (name, secret)
values ('tick', encode(extensions.gen_random_bytes(32), 'hex'))
on conflict (name) do nothing;